/**
 * Notion Node - Version 3
 * Discriminator: resource=user, operation=getAll
 */


interface Credentials {
  notionApi: CredentialReference;
  notionOAuth2Api: CredentialReference;
}

/** Get many child blocks */
export type NotionV3UserGetAllParams = {
  resource: 'user';
  operation: 'getAll';
  authentication?: 'apiKey' | 'oAuth2' | Expression<string>;
/**
 * Whether to return all results or only up to a given limit
 * @default false
 */
    returnAll?: boolean | Expression<boolean>;
/**
 * Max number of results to return
 * @displayOptions.show { returnAll: [false] }
 * @default 50
 */
    limit?: number | Expression<number>;
};

export type NotionV3UserGetAllOutput = {
  object?: string;
  id?: string;
  name?: string | null;
  avatar_url?: string | null;
  type?: string;
  person?: {
    email?: string;
    email_verified?: boolean;
  };
  bot?: Record<string, unknown>;
};

export type NotionV3UserGetAllNode = {
  type: 'n8n-nodes-base.notion';
  version: 3;
  config: NodeConfig<NotionV3UserGetAllParams> & { credentials?: Credentials };
  output?: Items<NotionV3UserGetAllOutput>;
};